export function getBereshitPhraseMapping(lang: string): RevealedPhrase[] {
  const normalizedLang = lang === 'zh-hans' || lang === 'zh-hant' ? 'zh' : lang;
  return BERESHIT_PHRASE_MAPPING[normalizedLang] || BERESHIT_PHRASE_MAPPING.en;
}

/** Verse-specific revealed insights (book ref is lowercase, e.g. "genesis") */
export const VERSE_REVEALED_INSIGHTS: Record<string, Record<string, string>> = {
  'genesis 1:1': BERESHIT_REVEALED_SENTENCE,
};

export function getVerseRevealedSentence(
  book: string,
  chapter: number,
  verse: number,
  lang: string,
): string | null {
  // Normalize book (genesis, Genesis, etc.)
  const bookNorm = String(book).toLowerCase().trim();
  const key = `${bookNorm} ${chapter}:${verse}`;
  const insights = VERSE_REVEALED_INSIGHTS[key];
  if (!insights) {
    return null;
  }
  const normalizedLang = lang === 'zh-hans' || lang === 'zh-hant' ? 'zh' : lang;
  return insights[normalizedLang] || insights.en || null;
}

