// Map final forms to base letters for lookup
export const FINAL_TO_BASE: Record<string, string> = {
  ך: 'כ',
  ם: 'מ',
  ן: 'נ',
  ף: 'פ',
  ץ: 'צ',
};

/**
 * Decompose a Hebrew word into individual letters (consonants only, strip nikud)
 * Returns array of letter glyphs in visual order (RTL)
 */
export function decomposeHebrewWord(word: string): string[] {
  const letters: string[] = [];
  for (const char of word) {
    const code = char.charCodeAt(0);
    // Hebrew block: U+0590 to U+05FF
    if (code >= 0x05d0 && code <= 0x05ea) {
      letters.push(char);
    }
    // Exclude nikud/vowel points (U+05B0-U+05C7) and other diacritics
  }
  return letters;
}

/**
 * Normalize a letter for combination lookup (convert final to base)
 */
export function normalizeLetter(letter: string): string {
  return FINAL_TO_BASE[letter] || letter;
}

/**
 * Get meaning for a letter in user's language
 */
export function getLetterMeaning(letter: string, lang: string): string {
  const entry = HEBREW_LETTERS[letter] || HEBREW_LETTERS[FINAL_TO_BASE[letter]];
  if (!entry) {
    return letter;
  }
  return entry.meanings[lang] || entry.meanings.en || entry.name;
}

/** Generate all permutations of an array (for small arrays only) */
function permutations<T>(arr: T[]): T[][] {
  if (arr.length <= 1) {
    return [arr];
  }
  const result: T[][] = [];
  for (let i = 0; i < arr.length; i++) {
    const rest = arr.slice(0, i).concat(arr.slice(i + 1));
    for (const p of permutations(rest)) {
      result.push([arr[i], ...p]);
    }
  }
  return result;
}

/**
 * Get meaning for a letter combination in user's language.
 * Tries original order, reversed, and all permutations (for 3+ letters)
 * so tiles combine correctly regardless of drag order.
 */
export function getCombinationMeaning(letters: string[], lang: string): string | null {
  const normalized = letters.map(normalizeLetter);

  const tryKey = (key: string): string | null => {
    const entry = HEBREW_COMBINATIONS[key];
    if (entry) {
      return entry.meaning[lang] || entry.meaning.en || null;
    }
    return null;
  };

  // Try original order
  const key = normalized.join('');
  const result = tryKey(key);
  if (result) {
    return result;
  }

  // Try reversed
  const reversedKey = [...normalized].reverse().join('');
  const reversedResult = tryKey(reversedKey);
  if (reversedResult) {
    return reversedResult;
  }

  // For 3+ letters, try all permutations (Hebrew word order varies with drag)
  if (letters.length >= 3 && letters.length <= 6) {
    const perms = permutations(normalized);
    for (const perm of perms) {
      const permKey = perm.join('');
      const permResult = tryKey(permKey);
      if (permResult) {
        return permResult;
      }
    }
  }

  return null;
}

/** Check if letters array matches word (same letters, any order) */
export function lettersMatchWord(letters: string[], word: string): boolean {
  const normalized = letters.map(normalizeLetter).sort().join('');
  const wordLetters = decomposeHebrewWord(word).map(normalizeLetter).sort().join('');
  return normalized === wordLetters;
}

/**
 * Fallback meaning when no exact combination exists:
 * concatenate individual letter meanings (e.g. "א (ox) + ת (covenant)")
 */
export function getFallbackCombinationMeaning(letters: string[], lang: string): string {
  if (letters.length === 0) {
    return '';
  }
  if (letters.length === 1) {
    return getLetterMeaning(letters[0], lang);
  }
  const parts = letters.map((l) => `${l} (${getLetterMeaning(l, lang)})`);
  return parts.join(' + ');
}
