import React, { useEffect } from 'react';
// Import static assets
// Using a string path for the image source instead of direct import
// This avoids TypeScript module declaration issues
import { Box } from '@mui/material';

interface LoadingSpinnerProps {
  isLoading: boolean;
}

const LoadingSpinner: React.FC<LoadingSpinnerProps> = ({ isLoading }) => {
  // Get the current theme to determine if we're in dark mode

  // Animation effect for the dots
  useEffect(() => {
    if (!isLoading) {
      return;
    }
  }, [isLoading]);

  if (!isLoading) {
    return null;
  }

  return (
    <Box
      sx={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        width: '100%',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'transparent',
        zIndex: 9999,
      }}
    >
      <Box
        sx={{
          position: 'relative',
          width: '50px',
          height: '50px',
          '@keyframes spinner-rotate': {
            '0%': { transform: 'rotateZ(0deg)' },
            '100%': { transform: 'rotateZ(360deg)' },
          },
          '& .circle': {
            display: 'inline-block',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            margin: 'auto',
          },
          '& .centre': {
            width: '5px',
            height: '5px',
            border: '5px solid transparent',
            borderColor: (theme) =>
              theme.palette.mode === 'dark'
                ? 'transparent #777777 transparent #777777'
                : 'transparent #777777 transparent #777777',
            borderRadius: '50%',
            animation: 'spinner-rotate 1s 0s linear infinite',
          },
          '& .middle': {
            border: '1.25px solid',
            borderColor: (theme) =>
              theme.palette.mode === 'dark'
                ? 'transparent #FFF transparent #FFF'
                : 'transparent #111 transparent #111',
            width: '37.5px',
            height: '37.5px',
            borderRadius: '50%',
            animation: 'spinner-rotate 2s 0s linear infinite',
          },
          '& .outer': {
            border: '5px solid transparent',
            borderColor: (theme) =>
              theme.palette.mode === 'dark'
                ? 'transparent #aeaeae transparent #aeaeae'
                : 'transparent #aeaeae transparent #aeaeae',
            width: '42.5px',
            height: '42.5px',
            borderRadius: '50%',
            animation: 'spinner-rotate 3s 0s linear infinite',
          },
        }}
      >
        <Box className="circle centre" />
        <Box className="middle circle" />
        <Box className="outer circle" />
      </Box>
    </Box>
  );
};

export default LoadingSpinner;
