export interface VisibleVerse {
  book: string;
  chapter: number | string;
  verse: number | string;
  text: string;
  translation?: string;
}
export interface ReaderContext {
  book: string;
  chapter: number;
  translation: string;
  visibleVerses: VisibleVerse[];
  selectedVerse?: VisibleVerse;
}
export const translations: Record<string, { name: string; language: string }> = {
  kjv: { name: 'King James Version', language: 'en' },
  fbv: { name: 'Free Bible Version', language: 'en' },
  cuv: { name: 'Chinese Union Version', language: 'zh-Hant' },
  lut: { name: 'Lutherbibel', language: 'de' },
  'es-rv09': { name: 'Reina Valera 1909', language: 'es' },
  'it-db1885': { name: 'Diodati 1885', language: 'it' },
  'cs-bkr': { name: 'Bible kralická', language: 'cs' },
  'sv-skb': { name: 'Svenska Bibeln', language: 'sv' },
  'id-tsi': { name: 'Alkitab Indonesia', language: 'id' },
  'nl-nld1939': { name: 'Nederlandse Bijbel 1939', language: 'nl' },
  'vi-ovcb': { name: 'Kinh Thánh Việt', language: 'vi' },
};

/** Describes only visible scripture. Never spread account or API objects into JSON-LD. */
export function buildReaderSchema({
  book,
  chapter,
  translation,
  visibleVerses,
  selectedVerse,
}: ReaderContext) {
  const edition = translations[translation];
  if (!book || !Number.isInteger(chapter) || chapter < 1 || !edition || !visibleVerses.length) {
    return undefined;
  }
  const first = visibleVerses[0];
  if (
    visibleVerses.some(
      (v) =>
        v.book !== first.book ||
        Number(v.chapter) !== chapter ||
        !v.text ||
        !Number.isInteger(Number(v.verse)) ||
        Number(v.verse) < 1 ||
        (v.translation && v.translation !== translation),
    )
  ) {
    return undefined;
  }
  const selected =
    selectedVerse &&
    visibleVerses.find(
      (v) =>
        v.book === selectedVerse.book &&
        Number(v.chapter) === Number(selectedVerse.chapter) &&
        Number(v.verse) === Number(selectedVerse.verse) &&
        v.text === selectedVerse.text,
    );
  const name = `${book} ${chapter}`;
  return {
    '@context': 'https://schema.org',
    '@type': 'WebPage',
    url: 'https://revelationary.online/study/',
    name: `${name} — ${edition.name} | Revelationary`,
    inLanguage: edition.language,
    mainEntity: {
      '@type': 'Chapter',
      name,
      position: chapter,
      inLanguage: edition.language,
      isPartOf: {
        '@type': 'Book',
        name: book,
        bookEdition: edition.name,
        inLanguage: edition.language,
      },
      text: visibleVerses.map((v) => `${v.verse}. ${v.text}`).join('\n'),
      ...(selected
        ? {
            hasPart: {
              '@type': 'CreativeWork',
              name: `${name}:${selected.verse}`,
              text: selected.text,
              inLanguage: edition.language,
            },
          }
        : {}),
    },
  };
}
