export const fetchCount = (book: string): number | string => {
  if (!book) {
    return '';
  }

  // Trim spaces and make sure the format is correct
  const cleanBook = book.trim().replace(/\s+/g, '-');

  if (bookSources[cleanBook]) {
    return bookSources[cleanBook][1];
  }

  return '';
};

const setPageFromVerseParts = (
  setPage: React.Dispatch<React.SetStateAction<number>>,
  ver: string[],
): void => {
  const chapter = ver[0];
  if (chapter && /^\d+$/.test(chapter)) {
    setPage(Number(chapter));
    return;
  }
  setPage(1);
};

// SearchBar
export const handleSearch = async (
  e: React.KeyboardEvent<HTMLInputElement>,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  searchTerm: (term: string, language: string) => Promise<void>,
  setCount: React.Dispatch<React.SetStateAction<number | string>>,
  setPage: React.Dispatch<React.SetStateAction<number>>,
  setSearch?: React.Dispatch<React.SetStateAction<string>>,
): Promise<void> => {
  if (e.keyCode === 13) {
    const term = (e.target as HTMLInputElement).value;
    const t =
      Cookies.get('translation') ||
      (typeof localStorage !== 'undefined' ? localStorage.getItem('translation') : null) ||
      'kjv';
    // Check if search contains Chinese characters (for Chinese keyword searches)
    const hasChineseChars = /[\u4e00-\u9fa5]/.test(term);
    // Check if search contains German characters or common German patterns (ä, ö, ü, ß)
    const hasGermanChars = /[äöüßÄÖÜ]/.test(term);

    if ((term.match(/"/g) || []).length >= 2) {
      // Quoted phrase search — use active Bible translation (CDN index or kjvapp fallback)
      await searchTerm(term, t || 'kjv');
    } else {
      // Bible book search (without quotes)
      // First check if it's a German book name
      const germanBookMatch = detectGermanBookName(term);

      if (germanBookMatch) {
        // Handle German book name search
        const { englishName, remaining } = germanBookMatch;
        let ver: string[] = [];
        let m: RegExpExecArray | null;
        const regex = new RegExp('[0-9]+:[0-9]+', 'g'); // Match "1:1" format

        // Parse chapter:verse from the remaining part (after German book name)
        const trimmedRemaining = remaining.trim();
        if (trimmedRemaining) {
          // Try to find chapter:verse pattern (e.g., "1:1")
          while ((m = regex.exec(trimmedRemaining)) !== null) {
            if (m.index === regex.lastIndex) {
              regex.lastIndex++;
            }
            m.forEach((match) => {
              ver = match.split(':');
              return ver;
            });
          }

          // If no chapter:verse pattern found, check for just chapter number
          if (ver.length === 0) {
            const chapterMatch = trimmedRemaining.match(/^(\d+):?$/);
            if (chapterMatch) {
              ver = [chapterMatch[1]];
            }
          }
        }

        // Handle different chapter:verse combinations
        // Reconstruct the search term in German for display
        let displaySearchTerm = germanBookMatch.germanName;
        if (ver.length > 1) {
          // Has both chapter and verse (e.g., "Matthäus 1:1")
          displaySearchTerm = `${germanBookMatch.germanName} ${ver[0]}:${ver[1]}`;
          await fetchVerse(englishName, ver[0], ver[1], setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1 && trimmedRemaining.endsWith(':')) {
          // Ends with colon (e.g., "Matthäus 1:")
          displaySearchTerm = `${germanBookMatch.germanName} ${ver[0]}:`;
          await fetchVerse(englishName, ver[0] + ':', '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1) {
          // Just chapter number (e.g., "Matthäus 1" or "Matthäus1")
          displaySearchTerm = `${germanBookMatch.germanName} ${ver[0]}`;
          await fetchVerse(englishName, ver[0], '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else {
          // Just book name (e.g., "Matthäus")
          await fetchVerse(englishName, 1, '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        }
        // Update search bar with German term if setSearch is provided
        if (setSearch) {
          setSearch(displaySearchTerm);
        }
        return; // Exit early since we handled German book search
      }

      // Check if it's a Spanish book name
      const spanishBookMatch = detectSpanishBookName(term);

      if (spanishBookMatch) {
        // Handle Spanish book name search
        const { englishName, remaining } = spanishBookMatch;
        let ver: string[] = [];
        let m: RegExpExecArray | null;
        const regex = new RegExp('[0-9]+:[0-9]+', 'g'); // Match "1:1" format

        // Parse chapter:verse from the remaining part (after Spanish book name)
        const trimmedRemaining = remaining.trim();
        if (trimmedRemaining) {
          // Try to find chapter:verse pattern (e.g., "1:1")
          while ((m = regex.exec(trimmedRemaining)) !== null) {
            if (m.index === regex.lastIndex) {
              regex.lastIndex++;
            }
            m.forEach((match) => {
              ver = match.split(':');
              return ver;
            });
          }

          // If no chapter:verse pattern found, check for just chapter number
          if (ver.length === 0) {
            const chapterMatch = trimmedRemaining.match(/^(\d+):?$/);
            if (chapterMatch) {
              ver = [chapterMatch[1]];
            }
          }
        }

        let displaySearchTerm = spanishBookMatch.spanishName;

        if (ver.length === 2) {
          // Full chapter:verse (e.g., "Génesis 1:1")
          displaySearchTerm = `${spanishBookMatch.spanishName} ${ver[0]}:${ver[1]}`;
          await fetchVerse(englishName, ver[0], ver[1], setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1 && trimmedRemaining.endsWith(':')) {
          // Ends with colon (e.g., "Génesis 1:")
          displaySearchTerm = `${spanishBookMatch.spanishName} ${ver[0]}:`;
          await fetchVerse(englishName, ver[0] + ':', '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1) {
          // Just chapter number (e.g., "Génesis 1" or "Génesis1")
          displaySearchTerm = `${spanishBookMatch.spanishName} ${ver[0]}`;
          await fetchVerse(englishName, ver[0], '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else {
          // Just book name (e.g., "Génesis")
          await fetchVerse(englishName, 1, '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        }
        // Update search bar with Spanish term if setSearch is provided
        if (setSearch) {
          setSearch(displaySearchTerm);
        }
        return; // Exit early since we handled Spanish book search
      }

      // Check if it's a Chinese book name
      const chineseBookMatch = detectChineseBookName(term);

      if (chineseBookMatch) {
        // Handle Chinese book name search
        const { englishName, remaining } = chineseBookMatch;
        let ver: string[] = [];
        let m: RegExpExecArray | null;
        const regex = new RegExp('[0-9]+:[0-9]+', 'g'); // Match "1:1" format

        // Parse chapter:verse from the remaining part (after Chinese book name)
        const trimmedRemaining = remaining.trim();
        if (trimmedRemaining) {
          // Try to find chapter:verse pattern (e.g., "1:1")
          while ((m = regex.exec(trimmedRemaining)) !== null) {
            if (m.index === regex.lastIndex) {
              regex.lastIndex++;
            }
            m.forEach((match) => {
              ver = match.split(':');
              return ver;
            });
          }

          // If no chapter:verse pattern found, check for just chapter number
          if (ver.length === 0) {
            const chapterMatch = trimmedRemaining.match(/^(\d+):?$/);
            if (chapterMatch) {
              ver = [chapterMatch[1]];
            }
          }
        }

        // Handle different chapter:verse combinations
        // Reconstruct the search term in Chinese for display
        let displaySearchTerm = chineseBookMatch.chineseName;
        if (ver.length > 1) {
          // Has both chapter and verse (e.g., "创世记 1:1")
          displaySearchTerm = `${chineseBookMatch.chineseName} ${ver[0]}:${ver[1]}`;
          await fetchVerse(englishName, ver[0], ver[1], setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1 && trimmedRemaining.endsWith(':')) {
          // Ends with colon (e.g., "创世记 1:")
          displaySearchTerm = `${chineseBookMatch.chineseName} ${ver[0]}:`;
          await fetchVerse(englishName, ver[0] + ':', '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else if (ver.length === 1) {
          // Just chapter number (e.g., "创世记 1" or "创世记1")
          displaySearchTerm = `${chineseBookMatch.chineseName} ${ver[0]}`;
          await fetchVerse(englishName, ver[0], '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        } else {
          // Just book name (e.g., "创世记")
          await fetchVerse(englishName, 1, '', setData, setVerse, t || 'kjv');
          setCount(fetchCount(englishName));
          setPageFromVerseParts(setPage, ver);
        }
        // Update search bar with Chinese term if setSearch is provided
        if (setSearch) {
          setSearch(displaySearchTerm);
        }
        return; // Exit early since we handled Chinese book search
      }

      // Check if it's a Chinese text search (not a book name)
      // If search contains Chinese characters but didn't match a book name, treat as keyword search
      if (hasChineseChars) {
        // Use CUV API for Chinese keyword searches
        searchTerm(term, 'cuv');
        return;
      }

      // Check if it's a German text search (not a book name)
      // If search contains German characters but didn't match a book name, treat as keyword search
      if (hasGermanChars) {
        // Use LUT API for German keyword searches
        searchTerm(term, 'lut');
        return;
      }

      // Fall through to English book search logic
      const str = term.split(' ');
      let m: RegExpExecArray | null;
      let ver: string[] = [];

      if (str.length >= 1 && !str.join(' ').includes('"')) {
        const joined = str.join(' ');
        const lwrCase = booksArr.map((book) => book.toLowerCase());
        const matchBook = booksArr.includes(str[0]) || lwrCase.includes(str[0].toLowerCase());
        const matchBookWithNumbers = checkNumbers(joined) as string;
        const regex = new RegExp('[0-9]*:[0-9]*', 'gm');
        const isKnownBookName =
          matchBook ||
          (typeof matchBookWithNumbers === 'string' &&
            matchBookWithNumbers.length > 0 &&
            booksArr.some(
              (book) => book.toLowerCase() === matchBookWithNumbers.toLowerCase().trim(),
            ));

        if (str.length === 1 && !isKnownBookName && !/\d/.test(joined)) {
          await searchTerm(`"${term.trim()}"`, t || 'kjv');
          return;
        }

        if (matchBook) {
          while ((m = regex.exec(joined)) !== null) {
            if (m.index === regex.lastIndex) {
              regex.lastIndex++;
            }
            m.forEach((match) => {
              ver = match.split(':');
              return ver;
            });
          }
          if (ver.length > 1 && !str.join(' ').includes('"')) {
            await fetchVerse(str[0].trim(), ver[0], ver[1], setData, setVerse, t || 'kjv');
            setCount(fetchCount(str[0].trim()));
            setPageFromVerseParts(setPage, ver);
          } else if (ver.length === 1 && term.endsWith(':')) {
            await fetchVerse(str[0].trim(), ver[0] + ':', '', setData, setVerse, t || 'kjv');
            setCount(fetchCount(str[0].trim()));
            setPageFromVerseParts(setPage, ver);
          } else if (ver.length === 1) {
            await fetchVerse(str[0].trim(), ver[0] + ':', '', setData, setVerse, t || 'kjv');
            setCount(fetchCount(str[0].trim()));
            setPageFromVerseParts(setPage, ver);
          } else {
            await fetchVerse(str[0].trim(), 1, '', setData, setVerse, t || 'kjv');
            setCount(fetchCount(str[0].trim()));
            setPage(1);
          }
        } else if (matchBookWithNumbers && isKnownBookName) {
          while ((m = regex.exec(joined)) !== null) {
            if (m.index === regex.lastIndex) {
              regex.lastIndex++;
            }
            m.forEach((match) => {
              ver = match.split(':');
              return ver;
            });
          }
          if (ver.length > 1) {
            await fetchVerse(
              matchBookWithNumbers.trim(),
              ver[0],
              ver[1],
              setData,
              setVerse,
              t || 'kjv',
            );
            setCount(await fetchCount(matchBookWithNumbers.trim()));
            setPageFromVerseParts(setPage, ver);
          } else if (ver.length === 1) {
            await fetchVerse(
              matchBookWithNumbers.trim(),
              ver[0],
              '',
              setData,
              setVerse,
              t || 'kjv',
            );
            setCount(await fetchCount(matchBookWithNumbers.trim()));
            setPageFromVerseParts(setPage, ver);
          } else {
            await fetchVerse(matchBookWithNumbers.trim(), 1, '', setData, setVerse, t || 'kjv');
            setCount(await fetchCount(matchBookWithNumbers.trim()));
            setPageFromVerseParts(setPage, ver);
          }
        } else if (isKnownBookName) {
          await fetchVerse(str[0].trim(), 1, '', setData, setVerse, t || 'kjv');
          setCount(await fetchCount(str[0].trim()));
          setPage(1);
        } else if (str.length === 1) {
          await searchTerm(`"${term.trim()}"`, t || 'kjv');
        }
      }
    }
  }
};

/* DATA DRIVEN */

const languageRootURL: any = {
  kjv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/en-kjv/books/',
  fbv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/en-fbv/books/',
  cuv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/cuv-zh-hant/books/',
  lut: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/lut/books/',
  'es-rv09': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/es-rv09/books/',
  'it-db1885': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/it-db1885/books/',
  'cs-bkr': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/cs-bkr/books/',
  'sv-skb': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/sv-skb/books/',
  'id-tsi': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/id-tsi/books/',
  'nl-nld1939':
    'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/nl-nld1939/books/',
  'vi-ovcb': 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/vi-ovcb/books/',
};

export const fetchVerse = async (
  book: string,
  chapter: string | number,
  verse: string | number,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  translation?: string,
): Promise<void> => {
  const checkBook = book.split(' ');
  const bk = checkBook[0];

  // Use bible-api for KJV, FBV, CUV, LUT, Spanish, and Italian translations
  if (
    translation === 'kjv' ||
    translation === 'fbv' ||
    translation === 'cuv' ||
    translation === 'lut' ||
    translation === 'es-rv09' ||
    translation === 'it-db1885' ||
    translation === 'cs-bkr' ||
    translation === 'sv-skb' ||
    translation === 'id-tsi' ||
    translation === 'nl-nld1939' ||
    translation === 'vi-ovcb' ||
    !translation
  ) {
    try {
      // Convert codebase book name to lowercase for folder name (e.g., firstSamuel -> firstsamuel)
      const folderBookName = bk.toLowerCase();

      // Build URL based on whether verse is specified
      let url: string;
      if (verse !== '' && verse !== undefined) {
        // Single verse: bibles/{translation}/books/{book}/chapters/{chapter}/verses/{verse}.json
        url = `${languageRootURL[translation || 'kjv']}${folderBookName}/chapters/${chapter}/verses/${verse}.json`;
      } else {
        // Chapter (all verses): bibles/{translation}/books/{book}/chapters/{chapter}.json
        url = `${languageRootURL[translation || 'kjv']}${folderBookName}/chapters/${chapter}.json`;
      }

      await fetch(url)
        .then((res) => res.json())
        .then(async (res) => {
          // bible-api responses match kjvapp.com format (arrays directly)
          // Chapter response: [{id, book, chapter, verse, text}, ...]
          // Verse response: [{id, book, chapter, verse, text}]
          if (res && Array.isArray(res) && res.length >= 1 && res[0].text) {
            const data = res.map(
              (v: { id: number; book: string; chapter: string; verse: string; text: string }) => ({
                ...v,
                translation: translation || 'kjv',
                text:
                  translation === 'fbv'
                    ? stripFbvCommentary(v.text, String(v.chapter), String(v.verse))
                    : v.text,
              }),
            );
            setData(data);
            setVerse(data);
          }
        });
    } catch (e) {
      devError('Unable to load the Bible passage.');
    }
  }
};

