import { devError } from '../../utils/developmentDiagnostics';
import { getModalSurface } from '../../utils/modalSurface';
import React, { useState, useEffect } from 'react';
import Typography from '@mui/material/Typography';
import Grid from '@mui/material/Grid';
import Paper from '@mui/material/Paper';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import { useTranslation } from '../../hooks/useTranslation';
import { translateBookName } from '../../utils/bookTranslations';

import { HighlightAlt, PolylineOutlined } from '@mui/icons-material';

import { stripFbvCommentary, cleanVerseText } from '../../utils/misc';
import BiotechIcon from '@mui/icons-material/Biotech';
import { Box, Chip, CircularProgress, Link } from '@mui/material';

import Accordion from '@mui/material/Accordion';
import AccordionSummary from '@mui/material/AccordionSummary';
import AccordionDetails from '@mui/material/AccordionDetails';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import Popover from '@mui/material/Popover';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';

const WP_API_URL = 'https://revelationary.org/wp-json/wp/v2/posts';
// Helper function to convert slug book name to API format
// e.g., "firstsamuel" -> "firstSamuel", "genesis" -> "genesis"
const slugToApiBookName = (slugBook: string): string => {
  const slugLower = slugBook.toLowerCase();
  // Map common slug formats to API format
  const bookMap: Record<string, string> = {
    firstsamuel: 'firstSamuel',
    secondsamuel: 'secondSamuel',
    firstkings: 'firstKings',
    secondkings: 'secondKings',
    firstchronicles: 'firstChronicles',
    secondchronicles: 'secondChronicles',
    firstcorinthians: 'firstCorinthians',
    secondcorinthians: 'secondCorinthians',
    firstthessalonians: 'firstThessalonians',
    secondthessalonians: 'secondThessalonians',
    firsttimothy: 'firstTimothy',
    secondtimothy: 'secondTimothy',
    firstpeter: 'firstPeter',
    secondpeter: 'secondPeter',
    firstjohn: 'firstJohn',
    secondjohn: 'secondJohn',
    thirdjohn: 'thirdJohn',
  };
  return bookMap[slugLower] || slugBook;
};

interface GuideProps {
  visible: string[];
  isShown: boolean;
  selectedVerse: {
    text: string;
    verse: number;
    book: string;
    chapter: number;
  }[];
  hover?: { text: string; book: string; chapter: number; verse: number };
  translation?: string;
}

const Guide: React.FC<GuideProps> = ({
  visible,
  isShown,
  selectedVerse,
  hover,
  translation = 'kjv',
}) => {
  const { t, language } = useTranslation(); // language ensures re-render on locale change

  interface PostMeta {
    related_posts?: number[];
    related_media?: any[];
    // add other meta fields as needed
  }

  interface Post {
    meta?: PostMeta;
    // add other post fields as needed
    [key: string]: any;
  }

  const [post, setPost] = useState<Post | null>(null);
  const [relatedPosts, setRelatedPosts] = useState<any[]>([]);
  const [loadingRelated, setLoadingRelated] = useState(false);
  const [relatedMedia, setRelatedMedia] = useState<any[]>([]);

  const [scienceMediaExpanded, setScienceMediaExpanded] = useState(false);
  const [linkedVersesExpanded, setLinkedVersesExpanded] = useState(false);
  const [popoverAnchorEl, setPopoverAnchorEl] = useState<HTMLElement | null>(null);
  const [popoverContent, setPopoverContent] = useState<{
    content: string;
    title: string;
  } | null>(null);
  const [linkedVerseTexts, setLinkedVerseTexts] = useState<Record<string, string>>({});
  const [loadingVerseText, setLoadingVerseText] = useState<Record<string, boolean>>({});

  // Build slug and fetch post when selectedVerse changes
  // Only fetch if selected verse is valid and matches current context
  useEffect(() => {
    if (selectedVerse.length === 0) {
      setPost(null);
      setRelatedPosts([]);
      setRelatedMedia([]);
      return;
    }

    // Validate that selected verse exists and has required properties
    const firstSelected = selectedVerse[0];
    if (!firstSelected || !firstSelected.book || !firstSelected.chapter || !firstSelected.verse) {
      setPost(null);
      setRelatedPosts([]);
      setRelatedMedia([]);
      return;
    }

    const controller = new AbortController();
    // Clear media when verse changes
    setRelatedMedia([]);

    const slug = `${firstSelected.book.toLowerCase().trim()}-${
      firstSelected.chapter
    }-${firstSelected.verse}`;
    fetch(`${WP_API_URL}?slug=${slug}`, { signal: controller.signal })
      .then((res) => res.json())
      .then((data) => {
        if (controller.signal.aborted) {
          return;
        }
        if (data && data.length > 0) {
          setPost(data[0]);
        } else {
          setPost(null);
        }
      })
      .catch(() => {
        if (controller.signal.aborted) {
          return;
        }
        devError('Error fetching post.');
        setPost(null);
      });
    return () => controller.abort();
  }, [selectedVerse]);

  // When post changes and Science & Media accordion is expanded, automatically load media
  useEffect(() => {
    if (scienceMediaExpanded && post?.meta?.related_media) {
      setRelatedMedia(post.meta.related_media);
    }
  }, [post, scienceMediaExpanded]);

  // When post changes and Linked Verses accordion is expanded, automatically load related posts
  useEffect(() => {
    const controller = new AbortController();
    if (linkedVersesExpanded && post?.meta?.related_posts) {
      setLoadingRelated(true);
      fetch(`${WP_API_URL}?include=${post.meta.related_posts.join(',')}&per_page=100`, {
        signal: controller.signal,
      })
        .then((res) => res.json())
        .then((data) => {
          if (controller.signal.aborted) {
            return;
          }
          setRelatedPosts(data);
          setLoadingRelated(false);
        })
        .catch(() => {
          if (controller.signal.aborted) {
            return;
          }
          devError('Error fetching related posts.');
          setLoadingRelated(false);
        });
    }
    return () => controller.abort();
  }, [post, linkedVersesExpanded]);

  // Each translation/list owns its requests; a late response cannot replace the new text.
  useEffect(() => {
    const controller = new AbortController();
    setLinkedVerseTexts({});
    setLoadingVerseText({});
    // Function to parse WordPress post slug and fetch verse text from translation API
    const fetchLinkedVerseText = async (postSlug: string, postId: number) => {
      setLoadingVerseText((prev) => ({ ...prev, [postId]: true }));

      try {
        // Parse slug format: "book-chapter-verse" (e.g., "genesis-1-3", "firstsamuel-1-1")
        const parts = postSlug.split('-');
        if (parts.length < 3) {
          devError('Invalid slug format.');
          setLoadingVerseText((prev) => ({ ...prev, [postId]: false }));
          return;
        }

        // Get verse number (last part)
        const verse = parseInt(parts[parts.length - 1], 10);
        // Get chapter number (second to last part)
        const chapter = parseInt(parts[parts.length - 2], 10);
        // Get book name (all parts before chapter, joined with dash)
        const bookSlug = parts.slice(0, -2).join('-');

        // Convert slug book name to API format
        const apiBookName = slugToApiBookName(bookSlug);

        // Get the first word for API (e.g., "firstSamuel" -> "firstSamuel", "genesis" -> "genesis")
        const bookApiName = apiBookName.split(' ')[0];

        // API URLs for different translations
        const languageRootURL: Record<string, string> = {
          kjv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/en-kjv/books/',
          fbv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/en-fbv/books/',
          cuv: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/cuv-zh-hant/books/',
          lut: 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/lut/books/',
          'es-rv09':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/es-rv09/books/',
          'it-db1885':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/it-db1885/books/',
          'cs-bkr':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/cs-bkr/books/',
          'sv-skb':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/sv-skb/books/',
          'id-tsi':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/id-tsi/books/',
          'nl-nld1939':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/nl-nld1939/books/',
          'vi-ovcb':
            'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles/vi-ovcb/books/',
        };

        let fetchUrl: string;
        let response: Response;
        let data: any;

        // Use bible-api for KJV, FBV, CUV, LUT, Spanish, and Italian translations
        if (
          translation === 'kjv' ||
          translation === 'fbv' ||
          translation === 'cuv' ||
          translation === 'lut' ||
          translation === 'es-rv09' ||
          translation === 'it-db1885' ||
          translation === 'cs-bkr' ||
          translation === 'sv-skb' ||
          translation === 'id-tsi' ||
          translation === 'nl-nld1939' ||
          translation === 'vi-ovcb' ||
          !translation
        ) {
          // Convert codebase book name to lowercase for folder name (e.g., firstSamuel -> firstsamuel)
          const folderBookName = bookApiName.toLowerCase();

          // Verse endpoint: bibles/{apiFolder}/books/{book}/chapters/{chapter}/verses/{verse}.json
          fetchUrl = `${languageRootURL[translation || 'kjv']}${folderBookName}/chapters/${chapter}/verses/${verse}.json`;

          response = await fetch(fetchUrl, { signal: controller.signal });
          data = await response.json();
          if (controller.signal.aborted) {
            return;
          }

          // bible-api responses match kjvapp.com format (arrays directly)
          // Verse response: [{id, book, chapter, verse, text}]
          if (data && Array.isArray(data) && data.length > 0 && data[0].text) {
            const raw = data[0].text;
            const verseText =
              translation === 'fbv'
                ? stripFbvCommentary(raw, String(chapter), String(verse))
                : cleanVerseText(raw, translation);
            setLinkedVerseTexts((prev) => ({ ...prev, [postId]: verseText }));
          } else {
            // Fallback to empty string if verse not found
            setLinkedVerseTexts((prev) => ({ ...prev, [postId]: '' }));
          }
        }
      } catch (error) {
        if (controller.signal.aborted) {
          return;
        }
        devError('Error fetching linked verse text.');
        setLinkedVerseTexts((prev) => ({ ...prev, [postId]: '' }));
      } finally {
        if (!controller.signal.aborted) {
          setLoadingVerseText((prev) => ({ ...prev, [postId]: false }));
        }
      }
    };

    relatedPosts.forEach((relatedPost: any) => {
      if (relatedPost.slug) {
        void fetchLinkedVerseText(relatedPost.slug, relatedPost.id);
      }
    });
    return () => controller.abort();
  }, [relatedPosts, translation]);

  const handleLinkedVersesOpen = (expanded: boolean) => {
    setLinkedVersesExpanded(expanded);
  };

  // Fetch related media when accordion is expanded
  const handleScienceMediaOpen = (expanded: boolean) => {
    setScienceMediaExpanded(expanded);
    if (expanded && post?.meta?.related_media) {
      setRelatedMedia(post.meta.related_media);
    }
  };

  return (
    <>
      {visible.includes('guide') && (
        <Grid
          key={language} // Force re-render when language changes
          item
          xs={12}
          md={4}
          lg={3}
          gap={1}
          sx={{ display: { xs: 'none', sm: 'flex' } }}
        >
          <Paper
            sx={{
              pb: 2,
              display: 'flex',
              flexDirection: 'column',
              height: 'auto',
            }}
            elevation={4}
          >
            <Accordion
              defaultExpanded={true}
              style={{
                backgroundColor: 'transparent',
              }}
            >
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography style={{ width: 'auto', fontSize: 15 }}>
                  <HighlightAlt
                    style={{
                      width: 24,
                      height: 24,
                      paddingBottom: 2,
                      verticalAlign: 'bottom',
                    }}
                  />
                  &nbsp;&nbsp;<span key={language}>{String(t('guide.guide'))}</span>
                </Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Card
                  sx={{
                    minWidth: 'auto',
                    background: 'transparent',
                    border: 'none',
                    boxShadow: 'none',
                    minHeight: 'fit-content',
                  }}
                >
                  <CardContent>
                    {!isShown && (
                      <Typography sx={{ fontSize: 14 }} color="text.secondary" gutterBottom>
                        <span key={language}>{String(t('guide.pleaseSelectVerse'))}</span>
                      </Typography>
                    )}
                    {isShown && (
                      <>
                        <Typography sx={{ fontSize: 14 }} color="text.secondary" gutterBottom>
                          <span key={language}>{String(t('guide.verseSelected'))}</span>
                          <br />
                          <br />
                        </Typography>
                        <Typography
                          variant="h5"
                          component="div"
                          sx={{
                            fontWeight: 200,
                            fontSize: '0.8rem',
                            display: 'inline-block',
                            columns: 1,
                          }}
                        >
                          {selectedVerse.length > 0
                            ? `"${selectedVerse[0].text}"`
                            : `"${hover && hover.text}"`}
                        </Typography>
                        <Typography sx={{ mb: 1.5, fontSize: '0.8rem' }} color="text.secondary">
                          <br />
                          {selectedVerse.length > 0
                            ? `${translateBookName(selectedVerse[0].book, t)} ${selectedVerse[0].chapter}:${selectedVerse[0].verse}`
                            : hover &&
                              translateBookName(hover.book, t) +
                                ' ' +
                                hover.chapter +
                                ':' +
                                hover?.verse}
                        </Typography>
                      </>
                    )}
                  </CardContent>
                </Card>
              </AccordionDetails>
            </Accordion>

            {/* Science & Media Accordion */}
            <Accordion onChange={(_, expanded) => handleScienceMediaOpen(expanded)}>
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography style={{ width: 'auto', fontSize: 15 }}>
                  <BiotechIcon
                    style={{
                      width: 24,
                      height: 24,
                      paddingBottom: 2,
                      verticalAlign: 'bottom',
                    }}
                  />
                  &nbsp;&nbsp;<span key={language}>{String(t('guide.scienceMedia'))}</span>
                </Typography>
              </AccordionSummary>
              {/* <AccordionDetails>
                <List sx={{ width: "100%" }}>
                  <Typography sx={{ fontSize: 12, cursor: "pointer" }}>
                    • Using Sound Waves To Create A Star
                  </Typography>
                </List>
              </AccordionDetails> */}
              <AccordionDetails>
                {selectedVerse.length === 0 || !post ? (
                  <Typography sx={{ fontSize: 14 }} key={language}>
                    {String(t('guide.pleaseClickVerse'))}
                  </Typography>
                ) : relatedMedia.length === 0 ? (
                  <Typography sx={{ fontSize: 14 }} key={language}>
                    {String(t('guide.noMediaFound'))}
                  </Typography>
                ) : null}
                {post &&
                  relatedMedia.length > 0 &&
                  relatedMedia.map((media, idx) => (
                    <Box key={idx} sx={{ mb: 1, flex: 1 }}>
                      <Link
                        style={{ fontSize: 12, color: '#888' }}
                        href={media.link}
                        target="_blank"
                        rel="noopener"
                      >
                        <img
                          src={media.img}
                          alt={media.title}
                          width={'100%'}
                          style={{ marginRight: 8, verticalAlign: 'middle' }}
                        />
                        {media.title}
                      </Link>
                    </Box>
                  ))}
              </AccordionDetails>
            </Accordion>

            {/* Linked Verses Accordion */}
            <Accordion onChange={(_, expanded) => handleLinkedVersesOpen(expanded)}>
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography style={{ width: 'auto', fontSize: 15 }}>
                  <PolylineOutlined
                    style={{
                      width: 24,
                      height: 24,
                      paddingBottom: 2,
                      verticalAlign: 'bottom',
                    }}
                  />
                  &nbsp;&nbsp;<span key={language}>{String(t('guide.linkedVerses'))}</span>
                </Typography>
              </AccordionSummary>
              {/* <AccordionDetails>
                <List sx={{ width: "100%" }}>
                  <Typography sx={{ fontSize: 12, cursor: "pointer" }}>
                    • John 1:1-3 • Hebrews 11:3 • Isaiah 45:18
                  </Typography>
                </List>
              </AccordionDetails> */}
              <AccordionDetails
                sx={{ overflowY: 'scroll', maxHeight: 300, msScrollRails: 'railed' }}
              >
                {loadingRelated && <CircularProgress size={20} />}
                {(selectedVerse.length === 0 ||
                  (relatedPosts.length === 0 && !loadingRelated) ||
                  !post) && (
                  <Typography sx={{ fontSize: 14 }} key={language}>
                    {String(t('guide.pleaseClickVerse'))}
                  </Typography>
                )}
                {post &&
                  relatedPosts.map((post) => {
                    // Parse the title to extract book name and translate it
                    // Format is typically "Genesis 3:15" or "1 Corinthians 1:1"
                    const title = post.title.rendered || '';
                    // Try to extract book name and chapter:verse
                    // Match patterns like "Genesis 3:15", "1 Corinthians 1:1", etc.
                    const bookVerseMatch = title.match(
                      /^([\d\s]*[a-zA-Z\u4e00-\u9fa5]+(?:\s+[a-zA-Z\u4e00-\u9fa5]+)*)\s+(\d+):(\d+)/,
                    );
                    let translatedLabel = title;

                    if (bookVerseMatch) {
                      const bookName = bookVerseMatch[1].trim();
                      const chapter = bookVerseMatch[2];
                      const verse = bookVerseMatch[3];
                      const translatedBookName = translateBookName(bookName, t);
                      translatedLabel = `${translatedBookName} ${chapter}:${verse}`;
                    }

                    // Use translated verse text if available, otherwise fallback to WordPress content
                    const verseText = linkedVerseTexts[post.id] || post.content?.rendered || '';
                    const isLoading = loadingVerseText[post.id];

                    return (
                      <Chip
                        key={post.id}
                        label={<span key={language}>{translatedLabel}</span>}
                        sx={{
                          m: 0.5,
                          fontSize: 12,
                          backgroundColor: (theme) =>
                            theme.palette.mode === 'light' ? '#0000001f' : '#212121',
                        }}
                        clickable
                        onClick={(e) => {
                          setPopoverContent({
                            content: isLoading
                              ? 'Loading...'
                              : verseText || post.content?.rendered || '',
                            title: translatedLabel,
                          });
                          setPopoverAnchorEl(e.currentTarget);
                        }}
                      />
                    );
                  })}
                <Popover
                  open={Boolean(popoverAnchorEl)}
                  anchorEl={popoverAnchorEl}
                  onClose={() => setPopoverAnchorEl(null)}
                  anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'left',
                  }}
                  transformOrigin={{
                    vertical: 'top',
                    horizontal: 'left',
                  }}
                  PaperProps={{
                    sx: (theme) => ({
                      ...getModalSurface(theme.palette.mode),
                      p: 2,
                      maxWidth: 320,
                    }),
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <Typography variant="subtitle2" sx={{ flexGrow: 1 }} key={language}>
                      {popoverContent?.title}
                    </Typography>
                    <IconButton
                      aria-label="close"
                      onClick={() => setPopoverAnchorEl(null)}
                      size="small"
                      sx={{ ml: 1 }}
                    >
                      <CloseIcon fontSize="small" />
                    </IconButton>
                  </Box>
                  <div
                    style={{ fontSize: 15 }}
                    dangerouslySetInnerHTML={{
                      __html: popoverContent?.content || '',
                    }}
                  />
                </Popover>
              </AccordionDetails>
            </Accordion>
            {/* Translations Accordion
            <Accordion>
              <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                <Typography style={{ width: "auto", fontSize: 15 }}>
                  <TranslateOutlined
                    style={{
                      width: 24,
                      height: 24,
                      paddingBottom: 2,
                      verticalAlign: "bottom",
                    }}
                  />
                  &nbsp;&nbsp; Translations
                </Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Box sx={{ mt: 1 }}>
                  <Select
                    fullWidth
                    displayEmpty
                    value={selectedTranslation}
                    onChange={(e) => setSelectedTranslation(e.target.value)}
                    size="small"
                    sx={{ background: "#212121", color: "#fff" }}
                  >
                    <MenuItem value="" disabled>
                      Select translation
                    </MenuItem>
                    <MenuItem value="esv">
                      English Standard Version (ESV)
                    </MenuItem>
                    <MenuItem value="niv">
                      New International Version (NIV)
                    </MenuItem>
                    <MenuItem value="kjv">King James Version (KJV)</MenuItem>
                  </Select>
                </Box>
              </AccordionDetails>
            </Accordion> */}

            <CardActions>{/* <Button size="small">Learn More</Button> */}</CardActions>
            {/* </Card> */}
          </Paper>
        </Grid>
      )}
    </>
  );
};

export default Guide;
