import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { applyMetadata } from '../../public-site/metadata';
import { buildReaderSchema, ReaderContext } from './readerSchema';

interface SEOProps {
  title?: string;
  description?: string;
  image?: string;
  reader?: ReaderContext;
  faqs?: { question: string; answer: string }[];
  noindex?: boolean;
}

export default function SEO({
  title = 'Bible study | Revelationary',
  description = 'Read and search the Bible. Explore Hebrew words and discuss scripture with Revelationary.',
  image = 'https://revelationary.online/logo512.png',
  reader,
  faqs,
  noindex = false,
}: SEOProps) {
  const location = useLocation();
  const readerData = reader ? buildReaderSchema(reader) : undefined;
  const url =
    location.pathname === '/'
      ? 'https://revelationary.online/study/'
      : `https://revelationary.online/study/#${location.pathname}`;
  const schema = noindex
    ? undefined
    : readerData ||
      (faqs
        ? {
            '@context': 'https://schema.org',
            '@type': 'FAQPage',
            url,
            mainEntity: faqs.map((faq) => ({
              '@type': 'Question',
              name: faq.question,
              acceptedAnswer: { '@type': 'Answer', text: faq.answer },
            })),
          }
        : { '@context': 'https://schema.org', '@type': 'WebPage', name: title, description, url });
  const encodedSchema = JSON.stringify(schema);
  const pageTitle = readerData?.name || title;
  useEffect(() => {
    applyMetadata({
      title: pageTitle,
      description,
      image,
      url,
      noindex,
      schema: encodedSchema ? JSON.parse(encodedSchema) : undefined,
    });
  }, [pageTitle, description, image, url, noindex, encodedSchema]);
  return null;
}

/** Dashboard and FAQ own their metadata. Other reader routes reveal no private data. */
export function ReaderRouteSEO() {
  const { pathname } = useLocation();
  if (pathname === '/' || pathname === '/faq' || pathname === '/blog') {
    return null;
  }
  return (
    <SEO
      title="Revelationary"
      description="Access your Revelationary account and Bible study tools."
      noindex
    />
  );
}
